using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new ChatClientBuilder(
    new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation(options =>
    {
        options.MaximumIterationsPerRequest = 10;
    })
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times to gather information from different angles.
        2. Save important findings as notes.
        3. After gathering enough information, retrieve all notes and produce a comprehensive summary.
        Always search at least 3 times with different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: tools);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research this topic and provide a comprehensive summary: {topic}",
    session: null,
    runOptions);

Console.WriteLine("=== Research Summary ===\n");
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 })
    {
        Console.WriteLine(message.Text);
    }
}

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a query. Returns search result snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration.
    // In production, integrate with Bing Search API or similar.
    Console.WriteLine($"  [Tool] Web search: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. Wikipedia overview: {query} is a widely discussed topic with multiple perspectives 
           covering history, current developments, and future outlook.
        2. Recent news: Latest developments in {query} show growing interest and new research 
           findings published in 2026.
        3. Expert analysis: Researchers highlight key challenges and opportunities in the 
           field of {query}, noting significant progress in recent years.
        """;
}

[Description("Save an important finding as a note for later summarization.")]
string SaveNote([Description("The note content to save")] string content)
{
    notes.Add(content);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved notes to use for summarization.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  [Tool] Retrieved {notes.Count} notes");
    return string.Join("\n---\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

